import {
  spawn,
  spawnSync,
  type ChildProcess,
  type SpawnOptions,
  type SpawnSyncOptions,
  type SpawnSyncReturns,
} from 'child_process';
import { subprocessEnvironment } from '../utils/subprocessEnvironment';
import {
  buildWindowsBatchShimCommand,
  buildWindowsShellCommand,
} from './OperatingSystemServices';

export type PackageManager =
  'npm' | 'npx' | 'yarn' | 'pnpm' | 'bun' | 'corepack';

export type ProcessCommand =
  | { packageManager: PackageManager; args: string[] }
  | { executable: string; args: string[] };

type ProcessInvocation = {
  file: string;
  args: string[];
  isShellRequired: boolean;
};

const NATIVE_WINDOWS_PACKAGE_MANAGERS: ReadonlySet<PackageManager> = new Set([
  'bun',
]);

const buildWindowsPackageManagerCommand = (
  packageManager: PackageManager,
  args: string[],
): string =>
  NATIVE_WINDOWS_PACKAGE_MANAGERS.has(packageManager)
    ? buildWindowsShellCommand({ executable: packageManager, args })
    : buildWindowsBatchShimCommand({ executable: packageManager, args });

export const resolveProcessInvocation = (
  command: ProcessCommand,
  platform: NodeJS.Platform = process.platform,
): ProcessInvocation => {
  if ('executable' in command) {
    return {
      file: command.executable,
      args: command.args,
      isShellRequired: false,
    };
  }
  if (platform === 'win32') {
    return {
      file: buildWindowsPackageManagerCommand(
        command.packageManager,
        command.args,
      ),
      args: [],
      isShellRequired: true,
    };
  }
  return {
    file: command.packageManager,
    args: command.args,
    isShellRequired: false,
  };
};

export const describeProcessCommand = (command: ProcessCommand): string =>
  'executable' in command ? command.executable : command.packageManager;

export const spawnProcess = (
  command: ProcessCommand,
  options: Omit<SpawnOptions, 'shell'>,
): ChildProcess => {
  const invocation = resolveProcessInvocation(command);
  return spawn(invocation.file, invocation.args, {
    ...options,
    env: options.env ?? subprocessEnvironment('packageManager'),
    shell: invocation.isShellRequired,
    windowsHide: true,
  });
};

export const spawnProcessSync = (
  command: ProcessCommand,
  options: Omit<SpawnSyncOptions, 'shell' | 'encoding'>,
): SpawnSyncReturns<string> => {
  const invocation = resolveProcessInvocation(command);
  return spawnSync(invocation.file, invocation.args, {
    ...options,
    env: options.env ?? subprocessEnvironment('packageManager'),
    encoding: 'utf8',
    shell: invocation.isShellRequired,
    windowsHide: true,
  });
};
